{
  "sets": [
    {
      "title": "National Affairs, Policy & Governance",
      "questions": [
        {
          "source_id": "1",
          "evidence": "his government is working to build the progressive Punjab they envision",
          "prompt": {
            "en": "What is the primary goal articulated by the Chief Minister for Punjab?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "To build the progressive Punjab they envision."
              }
            },
            {
              "id": "b",
              "text": {
                "en": "To focus solely on agricultural reforms."
              }
            },
            {
              "id": "c",
              "text": {
                "en": "To attract only foreign direct investment."
              }
            },
            {
              "id": "d",
              "text": {
                "en": "To reduce the state's historical debt."
              }
            }
          ],
          "correct_option_id": "a",
          "explanation": {
            "en": "The Chief Minister explicitly stated that \"his government is working to build the progressive Punjab they envision.\""
          }
        },
        {
          "source_id": "2",
          "evidence": "two SPOs were killed by the Army in a mistaken-identity case on November 11",
          "prompt": {
            "en": "According to Mr. Karra, what was the alleged cause of death for two SPOs in Kishtwar on November 11?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "A terrorist ambush."
              }
            },
            {
              "id": "b",
              "text": {
                "en": "A mistaken-identity case by the Army."
              }
            },
            {
              "id": "c",
              "text": {
                "en": "Cross-border shelling."
              }
            },
            {
              "id": "d",
              "text": {
                "en": "An accidental firing during training."
              }
            }
          ],
          "correct_option_id": "b",
          "explanation": {
            "en": "Mr. Karra stated that \"two SPOs were killed by the Army in a mistaken-identity case on November 11\"."
          }
        },
        {
          "source_id": "2",
          "evidence": "Congress is spreading misleading information to shift blame from terrorists to security forces",
          "prompt": {
            "en": "How did senior BJP leader Sharma characterize the Congress's actions regarding the Kishtwar incident?"
          },
          "options": [
            {
              "id": "a",
              "text": {
                "en": "As a constructive criticism of security protocols."
              }
            },
            {
              "id": "b",
              "text": {
                "en": "As an attempt to seek justice for the victims."
              }
            },
            {
              "id": "c",
              "text": {
                "en": "As spreading misleading information to shift blame from terrorists to security forces."
              }
            },
            {
              "id": "d",
              "text": {
                "en": "As a call for an independent inquiry."
              }
            }
          ],
          "correct_option_id": "c",
          "explanation": {
            "en": "Senior BJP leader Sharma alleged that \"Congress is spreading misleading information to shift blame from terrorists to security forces\"."
          }
        },
        {
          "source_id": "3",
          "evidence": "Bishop of Calcutta Reverend Paritosh Canning ruled out claims of religious conversion by institutions affiliated with the Churches of North India",
          "prompt": {
            "en": "What specific claim did Bishop of Calcutta Reverend Paritosh Canning refute regarding institutions affiliated with the Churches of North India?"
